funcs.render:
function render(src,caret,done){
  gSrc=src;
  var seq=++renderSeq;
  Bridge.parse(src).then(function(res){
    if(seq!==renderSeq)return;
    gNodes=Engine.ingestNative(res.blocks||[],gSrc);
    Engine.applyDocsets(gNodes);   // 文档级 @[page/margin/...] 设置生效(源码即权威)
    CFG=Engine.getConfig();
    gPages=Engine.layoutPages(gNodes);
    renderNodes();
    nativeDiags={src:gSrc,ds:res.diags||[]};
    updateDiagBar();
    if(caret)restoreCaret(caret);
    if(done)done();
  }).catch(function(e){
    document.getElementById('st-diag').textContent='解析失败';
    console.error(e);
  });
}

funcs.renderNodes:
function renderNodes(){
  var pane=document.getElementById('display-pane');
  pane.innerHTML='';
  for(var p=0;p<gPages.length;p++){
    var sheet=document.createElement('div');
    sheet.className='sheet';
    sheet.style.width=CFG.PAGE_W+'mm';
    sheet.style.minHeight=CFG.PAGE_H+'mm';
    sheet.style.padding=CFG.MARGIN+'mm';
    var paper=document.createElement('div');
    paper.className='paper';
    paper.contentEditable='true';
    paper.style.lineHeight=CFG.LINE_H;
    if(CFG.FONT)paper.style.fontFamily='\''+CFG.FONT+'\',serif';
    paper.style.setProperty('--fl',CFG.FIRSTLINE||'0em');
    paper.style.setProperty('--ps',CFG.PARA_SPACING||'0em');
    paper.dataset.page=p;
    for(var k=0;k<gPages[p].length;k++){
      var item=gPages[p][k], b=item.b;
      if(b.kind==='toc'){
        // 目录块:按标题节点生成,深度取 depth 参数,点击跳转
        var dep=parseInt((b.text.match(/depth:\s*(\d+)/)||[0,6])[1]);
        var toc=document.createElement('div');
        toc.className='tocblock'; toc.contentEditable='false';
        toc.dataset.bid=b.bid; toc.dataset.kind='toc'; toc.dataset.raw=b.text;
        var inner='<div class="toc-title">目录</div>';
        var tocCount=0;
        for(var ti=0;ti<gNodes.length;ti++){
          var hn=gNodes[ti];
          if(hn.kind!=='heading'||hn.level>dep)continue;
          tocCount++;
          inner+='<div class="toc-item lv'+hn.level+'" data-bid="'+hn.bid+'">'+Engine.escHtml(Engine.displayText(hn.text||''))+'</div>';
        }
        if(!tocCount)inner+='<div style="color:#9aa0a6;font-size:10pt">暂无标题,写作过程中自动生成</div>';
        toc.innerHTML=inner;
        toc.onclick=function(ev){
          var it=ev.target.closest('.toc-item');
          if(!it)return;
          var t=document.querySelector('#display-pane [data-bid="'+it.dataset.bid+'"]');
          if(t)t.scrollIntoView({behavior:'smooth',block:'start'});
        };
        paper.appendChild(toc);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='obj'){
        var obj=makeBlock(b,item);
        obj.style.cursor='pointer';
        obj.title='点击设置图片属性(宽度/对齐)';
        (function(bb){
          obj.addEventListener('click',function(){ openImagePanel(bb.bid) });
        })(b);
        paper.appendChild(obj);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='docset'){
        var d=document.createElement('div'); d.className='docset'; d.contentEditable='false'; d.textContent=b.text;
        paper.appendChild(d);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='comment'){
        var cm=document.createElement('div'); cm.className='comment-src'; cm.contentEditable='false';
        cm.textContent=b.text; cm.dataset.raw=b.text;
        paper.appendChild(cm);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='code'){
        var pre=document.createElement('div');
        pre.className='codeblock';
        pre.contentEditable='false';
        pre.dataset.bid=b.bid; pre.dataset.kind='code';
        pre.dataset.raw=b.text; pre.dataset.lang=b.lang||'';
        pre.innerHTML='<div class="code-lang">'+Engine.escHtml(b.lang)+'</div><pre><code>'+Engine.escHtml(b.text)+'</code></pre>';
        paper.appendChild(pre);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='math'){
        var mm=document.createElement('div');
        mm.className='mathblock'; mm.contentEditable='false';
        mm.dataset.bid=b.bid; mm.dataset.kind='math';
        mm.dataset.raw=b.text;
        mm.innerHTML='<div class="math-label">数学</div><div class="math-content">'+Engine.escHtml(b.text)+'</div>';
        paper.appendChild(mm);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='label'){
        var lb=document.createElement('div'); lb.className='lblref-block';
        lb.contentEditable='false'; lb.dataset.bid=b.bid; lb.dataset.kind='label';
        lb.dataset.raw=b.text;
        lb.textContent='📌 标签: '+b.text;
        paper.appendChild(lb);
        paper.appendChild(gapEl()); continue;
      }
      if(b.kind==='ref'){
        var rf=document.createElement('div'); rf.className='ref-block';
        rf.contentEditable='false'; rf.dataset.bid=b.bid; rf.dataset.kind='ref';
        rf.dataset.raw=b.text;
        rf.textContent='↦ 引用: '+b.text;
        paper.appendChild(rf);
        paper.appendChild(gapEl()); continue;
      }
      paper.appendChild(makeBlock(b,item));
      paper.appendChild(gapEl());
    }
    var folio=document.createElement('div');
    folio.className='folio'; folio.contentEditable='false'; folio.textContent='— '+(p+1)+' —';
    sheet.appendChild(paper); sheet.appendChild(folio);
    pane.appendChild(sheet);
  }
  renderOutline();
  renderStatus();
  updateGutter();
  var ta=document.getElementById('syntax-src');
  if(ta&&ta.value!==gSrc)ta.value=gSrc;
}

funcs.makeBlock:
function makeBlock(b,item){
  var html;
  if(item.whole||item.l0===undefined){
    html=Engine.blockHtml(b);
    var wrap=document.createElement('div');
    wrap.innerHTML=html;
    var inner=wrap.firstElementChild;
    inner.dataset.bid=b.bid;
    inner.dataset.kind=b.kind;
    if(b.level)inner.dataset.level=b.level;
    if(b.kind==='obj')inner.dataset.raw=b.text;
    return inner;
  }
  var text=item.partLines.slice(item.l0,item.l1).join('');
  var el=document.createElement('p');
  el.dataset.bid=b.bid;
  el.dataset.kind='para';
  el.dataset.l0=item.l0; el.dataset.l1=item.l1;
  if(item.l0>0)el.style.textIndent='0';  el.innerHTML=Engine.fmtH(text);
  return el;
}

funcs.renderOutline:
function renderOutline(){
  var ol=document.getElementById('outline');
  ol.innerHTML='';
  for(var i=0;i<gNodes.length;i++){
    var n=gNodes[i];
    if(n.kind!=='heading')continue;
    (function(n){
      var d=document.createElement('div');
      d.className='outline-item lv'+n.level;
      d.textContent=Engine.displayText(n.text);
      d.onclick=function(){
        var t=document.querySelector('#display-pane [data-bid="'+n.bid+'"]');
        if(t)t.scrollIntoView({behavior:'smooth',block:'start'});
      };
      ol.appendChild(d);
    })(n);
  }
}

funcs.renderStatus:
function renderStatus(){
  var chars=0, labels=0;
  for(var i=0;i<gNodes.length;i++){
    if(gNodes[i].kind==='obj')continue;
    if(gNodes[i].text)chars+=Engine.displayText(gNodes[i].text).replace(/\s/g,'').length;
    if(gNodes[i].text&&gNodes[i].text.indexOf('label')>=0)labels++;
  }
  document.getElementById('st-words').textContent=chars+' 字';
  document.getElementById('st-labels').textContent='标签 '+labels;
  document.getElementById('st-page').textContent='共 '+gPages.length+' 页';
}

funcs.onPaperInput:
function onPaperInput(e){
  if(repagTimer)clearTimeout(repagTimer);
  // 标点成步:句末标点立即落一步,且下一笔必开新语义步
  var punct=e&&e.data&&/[。？！，、；：.?!]/.test(e.data.slice(-1));
  if(punct){ applySyncNow(); histTime=0; return }
  repagTimer=setTimeout(applySyncNow,300);
}

funcs.swapSplit:
function swapSplit(){
  var ws=document.querySelector('.workspace');
  var dp=document.getElementById('display-pane');
  var sp=document.getElementById('syntax-pane');
  var st=document.getElementById('splitter');
  if(!dp||!sp)return;
  if(dp.nextElementSibling===sp){ ws.insertBefore(sp,dp); }
  else{ ws.insertBefore(dp,sp); }
  // 分隔条保持在两窗格之间
  if(st){ ws.insertBefore(st,sp); }
}

funcs.updateGutter:
function updateGutter(){
  var g=document.getElementById('gutter');
  var ta=document.getElementById('syntax-src');
  if(!g||!ta)return;
  var n=ta.value.split('\n').length;
  var out='';
  for(var i=1;i<=n;i++)out+='<div class="ln" data-ln="'+i+'">'+i+'</div>';
  if(g.dataset.count!==String(n)){ g.innerHTML=out; g.dataset.count=String(n) }
  g.scrollTop=ta.scrollTop;
}

funcs.setGutterCur:
function setGutterCur(line){
  var g=document.getElementById('gutter');
  if(!g)return;
  var prev=g.querySelector('.ln.cur');
  if(prev)prev.classList.remove('cur');
  var el=g.querySelector('.ln[data-ln="'+line+'"]');
  if(el){ el.classList.add('cur');
    // 保证当前行可见
    var top=el.offsetTop, h=el.offsetHeight;
    var gTop=g.scrollTop, gH=g.clientHeight;
    if(top<gTop||top+h>gTop+gH)g.scrollTop=Math.max(0,top-gH/2);
  }
}

funcs.caretLineNumber:
function caretLineNumber(){
  var ta=document.getElementById('syntax-src');
  if(!ta)return 1;
  return ta.value.substring(0,ta.selectionStart).split('\n').length;
}

funcs.applySyncNow:
function applySyncNow(){
  if(repagTimer){clearTimeout(repagTimer);repagTimer=null}
  if(lastEditSource==='syntax'||currentMode==='syntax'){
    // 语法视图/语法侧编辑:输入框即源码权威(§85),不再从纸面 DOM 反写
    var ta=document.getElementById('syntax-src');
    var taVal=ta?ta.value:'';
    if(taVal===gSrc)return;
    gSrc=taVal;
    if(currentMode==='split')render(gSrc);
    updateDiagBar();
      return;
  }
  // 纸面编辑:DOM 序列化回写源码(纸面即真实,不立即重建 DOM);
  // 节流后交 Aine 权威解析,返回后按需重排并恢复光标
  var newSrc=Engine.serializeAll();
  if(newSrc===gSrc)return;
  gSrc=newSrc;
  var ta=document.getElementById('syntax-src');
  if(ta)ta.value=gSrc;
  recordHist(gSrc,true);
  var caret=saveCaret();
  scheduleNativeRefresh(caret);
  updateDiagBar();
}

funcs.scheduleNativeRefresh:
function scheduleNativeRefresh(caret){
  refreshCaret=caret||refreshCaret||null;
  if(refreshTimer)clearTimeout(refreshTimer);
  refreshTimer=setTimeout(function(){
    refreshTimer=null;
    var c=refreshCaret; refreshCaret=null;
    render(gSrc,c);
  },500);
}

funcs.saveCaret:
function saveCaret(){
  var s=window.getSelection();
  if(!s.rangeCount)return null;
  var node=s.getRangeAt(0).startContainer;
  var blk=node.nodeType===1?(node.closest?node.closest('[data-bid]'):null):(node.parentElement&&node.parentElement.closest('[data-bid]'));
  if(!blk)return null;
  var r=s.getRangeAt(0).cloneRange();
  r.selectNodeContents(blk);
  r.setEnd(s.getRangeAt(0).endContainer,s.getRangeAt(0).endOffset);
  return{bid:blk.dataset.bid,off:r.toString().length};
}

funcs.restoreCaret:
function restoreCaret(c){
  if(!c)return;
  var el=document.querySelector('#display-pane [data-bid="'+c.bid+'"]');
  if(!el)return;
  var walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT), n, left=c.off, last=null, first=null;
  while((n=walker.nextNode())){ if(first===null)first=n; if(n.length>=left){ setSel(n,left); focusPaper(el); return } left-=n.length; last=n }
  if(last){ setSel(last,last.length) } else if(first){ setSel(first,0) }
  focusPaper(el);
}

funcs.setSel:
function setSel(node,off){
  var r=document.createRange(); r.setStart(node,off); r.collapse(true);
  var s=window.getSelection(); s.removeAllRanges(); s.addRange(r);
}

funcs.onPaperKey:
function onPaperKey(e){
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key==='b'){ e.preventDefault(); fmtCmd('bold'); return }
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key==='i'){ e.preventDefault(); fmtCmd('italic'); return }
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key==='u'){ e.preventDefault(); fmtCmd('underline'); return }
  if((e.ctrlKey||e.metaKey)&&e.key==='s'){ e.preventDefault(); doSave(); return }
  if(e.key==='Enter'&&e.target.closest&&e.target.closest('table')){ e.preventDefault(); return }
  if(e.key==='Backspace'){
    var c=saveCaret();
    if(c&&c.off===0){
      var el=document.querySelector('#display-pane [data-bid="'+c.bid+'"]');
      var paper=el&&el.closest('.paper');
      if(paper){
        var first=paper.querySelector('[data-bid]');
        if(first===el&&+c.bid>0){
          var prev=nodeByBid(+c.bid-1);
          if(prev&&prev.kind!=='table'&&prev.kind!=='obj'){ e.preventDefault(); mergeBlocks(+c.bid-1,+c.bid) }
        }
      }
    }
  }
  else if(e.key==='Delete'){
    var c2=saveCaret();
    if(c2){
      var el2=document.querySelector('#display-pane [data-bid="'+c2.bid+'"]');
      var paper2=el2&&el2.closest('.paper');
      if(paper2){
        var blocks=paper2.querySelectorAll('[data-bid]');
        var lastEl=blocks[blocks.length-1];
        var len=textLen(lastEl);
        if(lastEl===el2&&c2.off>=len){
          var next=nodeByBid(+c2.bid+1);
          if(next&&next.kind!=='table'&&next.kind!=='obj'){ e.preventDefault(); mergeBlocks(+c2.bid,+c2.bid+1) }
        }
      }
    }
  }
}

funcs.nodeByBid:
function nodeByBid(bid){
  for(var i=0;i<gNodes.length;i++){ if(gNodes[i].bid==bid)return gNodes[i] }
  return null;
}

funcs.mergeBlocks:
function mergeBlocks(keepBid,goneBid){
  var keep=nodeByBid(keepBid), gone=nodeByBid(goneBid);
  if(!keep||!gone)return;
  var keepEl=document.querySelector('#display-pane [data-bid="'+keepBid+'"]');
  var goneEl=document.querySelector('#display-pane [data-bid="'+goneBid+'"]');
  var keepText=keepEl?Engine.inlineSource(keepEl).trim():Engine.displayText(keep.text);
  var goneText=goneEl?Engine.inlineSource(goneEl).trim():Engine.displayText(gone.text);
  var junction=keepText.length;
  var lines=gSrc.split('\n');
  var mergedLine=Engine.blockPrefix(keep.kind,keep.level)+(keepText+' '+goneText).replace(/\s+/g,' ').trim();
  lines.splice(keep.srcStart,gone.srcEnd-keep.srcStart,mergedLine);
  var caret={bid:keepBid,off:junction+1};
  render(lines.join('\n'));
  restoreCaret(caret);
  recordHist(gSrc,false);
}

funcs.fmtCmd:
function fmtCmd(cmd){
  if(inDisplayMode()){
    document.execCommand(cmd,false,null);
    onPaperInput();
  }else{
    var map={bold:['**','**'],italic:['_','_'],underline:['@[u]','@[/u]'],strikeThrough:['~~','~~'],superscript:['@[sup]','@[/sup]'],subscript:['@[sub]','@[/sub]']};
    if(map[cmd])wrapSyntax(map[cmd][0],map[cmd][1]);
  }
}

funcs.fmtCmdInline:
function fmtCmdInline(){
  if(inDisplayMode()){
    var s=window.getSelection();
    if(!s.rangeCount||s.isCollapsed)return;
    var r=s.getRangeAt(0);
    var b1=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest('[data-bid]');
    var b2=(r.endContainer.nodeType===1?r.endContainer:r.endContainer.parentElement).closest('[data-bid]');
    if(!b1||b1!==b2){ document.getElementById('findmsg').textContent='行内代码不能跨段落'; return }
    var code=document.createElement('code');
    code.appendChild(r.extractContents());
    r.insertNode(code);
    onPaperInput();
  }
  else wrapSyntax('`','`');
}

funcs.wrapSpan:
function wrapSpan(open, close, style, native){
  var s=window.getSelection();
  if(!s.rangeCount||s.isCollapsed)return false;
  var r=s.getRangeAt(0);
  var b1=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest('[data-bid]');
  var b2=(r.endContainer.nodeType===1?r.endContainer:r.endContainer.parentElement).closest('[data-bid]');
  if(!b1||b1!==b2){ document.getElementById('findmsg').textContent='该格式不能跨段落选择'; return false }
  var wrap=document.createElement(native?'code':'span');
  if(!native){
    wrap.dataset.cmd=open; wrap.dataset.close=close;
  }
  if(style)for(var k in style)wrap.style[k]=style[k];
  wrap.appendChild(r.extractContents());
  r.insertNode(wrap);
  s.removeAllRanges();
  var nr=document.createRange(); nr.selectNodeContents(wrap); s.addRange(nr);
  return true;
}

funcs.applyColor:
function applyColor(v){
  if(inDisplayMode()){ document.execCommand('foreColor',false,v); onPaperInput() }
  else wrapSyntax('@[color '+v+']','@[/color]');
}

funcs.applyMark:
function applyMark(v){
  if(inDisplayMode()){
    var s=window.getSelection();
    if(!s.rangeCount||s.isCollapsed)return;
    if(wrapSpan('@[mark '+v+']','@[/mark]',{background:v},false))onPaperInput();
  }
  else wrapSyntax('@[mark '+v+']','@[/mark]');
}

funcs.applySize:
function applySize(v){
  if(!v)return;
  if(inDisplayMode()){
    var s=window.getSelection();
    if(!s.rangeCount||s.isCollapsed){ document.getElementById('findmsg').textContent='请先选中要设置字号的文字'; return }
    if(wrapSpan('@[size '+v+']','@[/size]',{fontSize:v+'pt'},false))onPaperInput();
  }
  else wrapSyntax('@[size '+v+']','@[/size]');
}

funcs.applyFont:
function applyFont(v){
  if(!v)return;
  if(inDisplayMode()){
    var s=window.getSelection();
    if(!s.rangeCount||s.isCollapsed)return;
    if(wrapSpan('@[font "'+v+'"]','@[/font]',{fontFamily:"'"+v+"',serif"},false))onPaperInput();
  }
  else wrapSyntax('@[font "'+v+'"]','@[/font]');
  document.getElementById('sel-font').selectedIndex=0;
}

funcs.applyStyle:
function applyStyle(lv){
  if(lv==='')return;
  var bel=caretBlock();
  var bid;
  if(bel)bid=+bel.dataset.bid;
  else{
    var ta=document.getElementById('syntax-src');
    if(!ta)return;
    var pos=ta.value.substring(0,ta.selectionStart).split('\n').length-1;
    for(var i=0;i<gNodes.length;i++){ if(pos>=gNodes[i].srcStart&&pos<gNodes[i].srcEnd){ bid=gNodes[i].bid; break } }
    if(bid===undefined)return;
  }
  var b=nodeByBid(bid);
  if(!b)return;
  var el=document.querySelector('#display-pane [data-bid="'+bid+'"]');
  var body=el?Engine.inlineSource(el).replace(/^#+\s*/,'').trim():Engine.displayText(b.text);
  var lines=gSrc.split('\n');
  lines.splice(b.srcStart,b.srcEnd-b.srcStart,'#'.repeat(+lv)+' '+body);
  setSrc(lines.join('\n'));
  restoreCaret({bid:bid,off:0});
}

funcs.listCmd:
function listCmd(kind){
  if(inDisplayMode()){
    document.execCommand(kind==='ul'?'insertUnorderedList':'insertOrderedList',false,null);
    onPaperInput();
  }else insertSyntax(kind==='ul'?'\n- 列表项\n':'\n1. 列表项\n');
}

funcs.insertBlock:
function insertBlock(kind){
  var snippets={
    quote:['> 引用内容'],
    hr:['---'],
    link:['@[link 链接文字 url: https://example.com]'],
    image:null,
    table:['@[table demo]','| 列1 | 列2 |','| --- | --- |','| 内容 | 内容 |','@[/table]'],
    toc:['@[toc depth: 2]'],
    comment:['@[comment 批注内容,不参与渲染]'],
    footnote:['@[footnote 1 脚注内容]'],
    math:['@[m]','E = mc^2','@[/m]'],
    label:['@[label 引用名]']
  };
  if(kind==='image'){pickImageInsert();return}
  if(kind==='date'){
    var d=new Date();
    insertRawLine(d.getFullYear()+' 年 '+(d.getMonth()+1)+' 月 '+d.getDate()+' 日');
    return;
  }
  var ins=snippets[kind];
  if(!ins)return;
  var renameNew=(kind==='label'||kind==='link');   // 插入后选中占位文字,直接输入即改名
  if(inDisplayMode()){
    // 在当前块后插入新块
    var bel=caretBlock();
    var _caret=saveCaret();
    var insertAt=gSrc.split('\n').length;
    if(bel){
      var b=nodeByBid(bel.dataset.bid);
      if(b)insertAt=b.srcEnd;
    }
    var lines=gSrc.split('\n');
    var insert=ins.slice();
    if(insertAt<lines.length&&lines[insertAt].trim()!=='')insert=insert.concat(['']);
    if(insertAt>0&&lines[insertAt-1].trim()!=='')insert=[''].concat(insert);
    lines.splice.apply(lines,[insertAt,0].concat(insert));
    setSrc(lines.join('\n'));
    if(renameNew){
      // 选中刚插入块的占位文字(链接文字/书签名),直接输入即覆盖
      var nb=document.querySelectorAll('#display-pane [data-bid]');
      var lastBlk=nb[nb.length-1];
      if(lastBlk){
        var w=document.createTreeWalker(lastBlk,NodeFilter.SHOW_TEXT);
        var tn=w.nextNode();
        var rr=document.createRange();
        if(tn)rr.selectNodeContents(tn); else rr.selectNodeContents(lastBlk);
        var ss=window.getSelection(); ss.removeAllRanges(); ss.addRange(rr);
      }
      return;
    }
    restoreCaret(_caret);
  }else insertSyntax('\n'+ins.join('\n')+'\n');
}

funcs.selTr:
function selTr(){
  var s=window.getSelection();
  if(!s.rangeCount)return null;
  var n=s.getRangeAt(0).startContainer;
  var el=n.nodeType===1?n:n.parentElement;
  return el?el.closest('tr'):null;
}

funcs.selCell:
function selCell(){
  var s=window.getSelection();
  if(!s.rangeCount)return null;
  var n=s.getRangeAt(0).startContainer;
  var el=n.nodeType===1?n:n.parentElement;
  return el?el.closest('th,td'):null;
}

funcs.tblInsRow:
