  }else{
    var ta=document.getElementById('syntax-src');
    var from=ta.selectionEnd;
    var i=findIdxOf(gSrc,q,from);
    if(i<0)i=findIdxOf(gSrc,q,0);
    if(i>=0){ta.focus();ta.setSelectionRange(i,i+q.length)}
  }
}

