funcs.replaceOne:
function replaceOne(){
  var q=document.getElementById('findbox').value;
  var r=document.getElementById('replacebox').value;
  if(!q)return;
  var src=gSrc;
  var i;
  var ta=document.getElementById('syntax-src');
  if(inDisplayMode()&&window.getSelection&&!window.getSelection().isCollapsed){
    i=saveCaret()?src.indexOf(q):src.indexOf(q);
  }else if(ta&&document.activeElement===ta){
    i=src.indexOf(q,ta.selectionStart);
  }else{
    i=src.indexOf(q);
  }
  if(i<0)i=src.indexOf(q);
  if(i<0){document.getElementById('findmsg').textContent='未找到';return}
  setSrc(src.substring(0,i)+r+src.substring(i+q.length));
  document.getElementById('findmsg').textContent='已替换 1 处';
}

funcs.replaceAll:
function replaceAll(){
  var q=document.getElementById('findbox').value;
  var r=document.getElementById('replacebox').value;
  if(!q)return;
  var cs=cs0(),whole=cw0();
  var starts=matchStarts(gSrc,q,cs,whole);
  if(!starts.length){
    highlightAll(q);
    document.getElementById('findmsg').textContent='未找到';
    return;
  }
  var out='',last=0;
  starts.forEach(function(st){
    out+=gSrc.substring(last,st)+r;
    last=st+q.length;
  });
  out+=gSrc.substring(last);
  setSrc(out);
  highlightAll(q);
  document.getElementById('findmsg').textContent='已替换 '+starts.length+' 处';
}

funcs.setDocsetLine:
function setDocsetLine(matchRe,newLine){
  var lines=gSrc.split('\n');
  for(var i=0;i<lines.length;i++){
    if(matchRe.test(lines[i])){
      if(newLine===null)lines.splice(i,1); else lines[i]=newLine;
      setSrc(lines.join('\n'));
      return;
    }
  }
  // 未找到:插入文件头 @[...] 设置区末尾
  var at=0;
  while(at<lines.length&&lines[at].indexOf('@[')===0)at++;
  lines.splice(at,0,newLine);
  setSrc(lines.join('\n'));
}

funcs.applyPaper:
function applyPaper(v){
  var sz=Engine.PAPER_SIZES[v]; if(!sz)return;
  setDocsetLine(/^@\[page\s/,'@[page '+v+']');
}

funcs.applyMargin:
function applyMargin(v){
  if(v==='custom'){
    var inp=document.getElementById('margin-custom');
    inp.style.display='block'; inp.focus();
    return;
  }
  setDocsetLine(/^@\[margin\s/,'@[margin '+v+'mm]');
}

funcs.applyMarginCustom:
function applyMarginCustom(v){
  var x=parseFloat(v);
  if(x>=5&&x<=60) setDocsetLine(/^@\[margin\s/,'@[margin '+x+'mm]');
}

funcs.applyLineSpacing:
function applyLineSpacing(v){
  if(v==='custom'){
    var inp=document.getElementById('linesp-custom');
    inp.style.display='block'; inp.focus();
    return;
  }
  setDocsetLine(/^@\[line-spacing\s/,'@[line-spacing '+v+']');
}

funcs.toggleOrientation:
function toggleOrientation(){
  // 横向为会话级覆盖(规范暂无横向语法):只重排,不写回源码
  Engine.setPage({PAGE_W:CFG.PAGE_H,PAGE_H:CFG.PAGE_W});
  renderKeep();
  document.getElementById('btn-orient').textContent=CFG.PAGE_W>CFG.PAGE_H?'横向':'纵向';
}

funcs.toggleFirstLine:
function toggleFirstLine(){
  var lines=gSrc.split('\n');
  var idx=-1;
  for(var i=0;i<lines.length;i++){ if(lines[i].indexOf('@[first-line')===0){idx=i;break} }
  if(idx>=0){ lines.splice(idx,1); document.getElementById('btn-firstline').classList.remove('on') }
  else{
    var at=0;
    for(var j=0;j<lines.length;j++){ if(lines[j].indexOf('@[')===0)at=j+1; else break }
    lines.splice(at,0,'@[first-line 2em]');
    document.getElementById('btn-firstline').classList.add('on');
  }
  setSrc(lines.join('\n'));
}

funcs.exportFile:
function exportFile(kind){
  if(kind==='txt'){saveWithPicker(fname('txt'),gSrc);return}
  if(kind==='md'){
    var out=[],lines=gSrc.split('\n');
    for(var i=0;i<lines.length;i++){
      var t=lines[i];
      if(/^@\[(page|margin|font|size|line-spacing|first-line|theme|toc|numbering)\s/.test(t))continue;
      if(/^@\[table/.test(t)||/^@\[\/table\]/.test(t))continue;
      if(/^@\[comment/.test(t)){while(i<lines.length&&lines[i].indexOf('@[/comment]')<0)i++;continue}
      var m=t.match(/^@\[image\s+([^\]]+)\]$/);
      if(m){out.push('!['+m[1]+']('+m[1]+')');continue}
      t=t.replace(/@\[link\s+([^\]]+?)\s+url:\s*([^\]]+)\]/g,'[$1]($2)');
      t=t.replace(/@\[u\]((?:.|])*?)@\[\/u\]/g,'<u>$1</u>');
      out.push(t);
    }
    saveWithPicker(fname('md'),out.join('\n'));
    return;
  }
  if(kind==='html'||kind==='doc'){
    var papers=document.querySelectorAll('#display-pane .paper');
    var body='';
    papers.forEach(function(pp){body+=pp.innerHTML});
    var html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>Awen 文档</title><style>'
      +'body{margin:0;background:#e8e9eb}'
      +'.sheet{width:'+CFG.PAGE_W+'mm;min-height:'+CFG.PAGE_H+'mm;background:#fff;margin:16px auto;padding:'+CFG.MARGIN+'mm;box-sizing:border-box;font-family:Georgia,"Times New Roman","Noto Serif SC","Microsoft YaHei",serif;font-size:11pt;line-height:'+CFG.LINE_H+';color:#303238}'
      +'h1{font-size:22pt}h2{font-size:15pt}h3{font-size:13pt}h4{font-size:12pt}h5{font-size:11pt}h6{font-size:10.5pt}'
      +'p{text-indent:2em;margin:0}strong,b{font-weight:700}em,i{font-style:italic}del,s{text-decoration:line-through}u{text-decoration:underline}'
      +'code{font-family:Consolas,monospace;font-size:.87em;background:#f0f1f2;padding:1px 4px;border-radius:3px}'
      +'hr{border:none;border-top:1px solid #ccc}blockquote{border-left:3px solid #c8cad0;padding:2px 14px;color:#5a5c60;margin:0}'
      +'ul,ol{margin:0;padding-left:2.4em}table{width:100%;border-collapse:collapse;font-size:10.5pt}'
      +'th,td{border:1px solid #d0d2d5;padding:4px 8px;text-align:left}th{background:#f5f5f6}'
      +'.docset{color:#c8cad0;font-size:8pt}.comment-src{background:#fffbe8;color:#b09a3e;font-size:9pt}'
      +'</style></head><body>'+body+'</body></html>';
    saveWithPicker(fname(kind==='html'?'html':'doc'),html);
  }
}

funcs.buildSyntaxPane:
function buildSyntaxPane(){
  if(document.getElementById('syntax-src'))return;
  var pane=document.getElementById('syntax-pane');
  var sheet=document.createElement('div');
  sheet.className='sheet';
  var src=document.createElement('div');
  src.className='src-wrap';
  var gutter=document.createElement('div');
  gutter.id='gutter'; gutter.className='gutter';
  var ta=document.createElement('textarea');
  ta.id='syntax-src'; ta.spellcheck=false;
  ta.style.cssText='flex:1;height:'+(CFG.PAGE_H-2*CFG.MARGIN-2)+'mm;border:0;outline:0;resize:none;background:transparent;font:inherit;color:inherit;white-space:pre;overflow:auto';
  src.appendChild(gutter);
  src.appendChild(ta);
  sheet.appendChild(src);
  pane.appendChild(sheet);
  // 分屏拖拽分隔条(插在两窗格之间)
  var ws=document.querySelector('.workspace');
  var dp=document.getElementById('display-pane');
  var splitter=document.createElement('div');
  splitter.id='splitter'; splitter.className='splitter'; splitter.style.display='none';
  ws.insertBefore(splitter, pane);
  splitter.addEventListener('mousedown',function(e){
    e.preventDefault();
    var move=function(ev){
      var rect=ws.getBoundingClientRect();
      var pct=Math.min(85,Math.max(15,((ev.clientX-rect.left)/rect.width)*100));
      if(dp.nextElementSibling===pane){ dp.style.flex='1 1 auto'; pane.style.flex='0 0 '+(100-pct)+'%' }
      else{ dp.style.flex='1 1 auto'; pane.style.flex='0 0 '+pct+'%' }
    };
    var up=function(){ document.removeEventListener('mousemove',move); document.removeEventListener('mouseup',up) };
    document.addEventListener('mousemove',move);
    document.addEventListener('mouseup',up);
  });
  ta.addEventListener('scroll',function(){
    gutter.scrollTop=ta.scrollTop;
    if(!window.scrollSyncLock&&currentMode==='split'){
      window.scrollSyncLock='ta';
      var pane=document.getElementById('display-pane');
      var ratio=ta.scrollTop/Math.max(1,ta.scrollHeight-ta.clientHeight);
      pane.scrollTop=ratio*Math.max(1,pane.scrollHeight-pane.clientHeight);
      setTimeout(function(){window.scrollSyncLock=null},50);
    }
  });
  document.getElementById('display-pane').addEventListener('scroll',function(){
    if(currentMode!=='split'||window.scrollSyncLock)return;
    window.scrollSyncLock='dp';
    var ta2=document.getElementById('syntax-src');
    if(!ta2)return;
    var pane2=document.getElementById('display-pane');
    var ratio=pane2.scrollTop/Math.max(1,pane2.scrollHeight-pane2.clientHeight);
    ta2.scrollTop=ratio*Math.max(1,ta2.scrollHeight-ta2.clientHeight);
    gutter.scrollTop=ta2.scrollTop;
    setTimeout(function(){window.scrollSyncLock=null},50);
  });
  ta.addEventListener('input',function(){
    lastEditSource='syntax';
    recordHist(ta.value,true);
    setGutterCur(caretLineNumber());
    if(repagTimer)clearTimeout(repagTimer);
    repagTimer=setTimeout(applySyncNow,300);
  });
  // 光标移动跟随行高亮
  ['keyup','click'].forEach(function(ev){
    ta.addEventListener(ev,function(){ setGutterCur(caretLineNumber()) });
  });
}

funcs.insertSyntax:
function insertSyntax(text){
  var ta=document.getElementById('syntax-src');
  if(!ta)return;
  var s=ta.selectionStart;
  ta.value=ta.value.substring(0,s)+text+ta.value.substring(ta.selectionEnd);
  ta.selectionStart=ta.selectionEnd=s+text.length;
  ta.focus();
  setSrc(ta.value);
}

funcs.wrapSyntax:
function wrapSyntax(open,close){
  var ta=document.getElementById('syntax-src');
  if(!ta)return;
  var s=ta.selectionStart,e=ta.selectionEnd;
  var sel=ta.value.substring(s,e)||'文本';
  ta.focus();
  ta.value=ta.value.substring(0,s)+open+sel+close+ta.value.substring(e);
  ta.selectionStart=s+open.length;
  ta.selectionEnd=s+open.length+sel.length;
  setSrc(ta.value);
}

funcs.recordHist:
function recordHist(text,merge){
  var now=Date.now();
  if(merge&&histIdx>=0&&histIdx===hist.length-1&&now-histTime<500){
    hist[histIdx]=text; histTime=now; markDirty(); return
  }
  hist=hist.slice(0,histIdx+1);
  hist.push(text);
  if(hist.length>300)hist.shift();
  histIdx=hist.length-1;
  histTime=now;
  markDirty();
}

funcs.markDirty:
function markDirty(){
  docDirty=true;
  updateTitle();
  updateUndoButtons();
  updateDiagBar();
}

funcs.doUndo:
function doUndo(){
  applySyncNow();
  if(histIdx<=0)return;
  histIdx--;
  applyHistory(hist[histIdx]);
}

funcs.doRedo:
function doRedo(){
  applySyncNow();
  if(histIdx>=hist.length-1)return;
  histIdx++;
  applyHistory(hist[histIdx]);
}

funcs.applyHistory:
function applyHistory(text){
  var caret=saveCaret();
  var ta=document.getElementById('syntax-src');
  if(ta)ta.value=text;
  render(text);
  // 与 setSrc 相同的序列化规范化(但 undo 不入史)
  var norm=Engine.serializeAll();
  if(norm!==gSrc){ render(norm); }
  restoreCaret(caret);
  updateDiagBar();
  updateUndoButtons();
  document.getElementById('st-diag').title='历史 '+histIdx+'/'+(hist.length-1);
}

funcs.setSrc:
function setSrc(s,caret){
  var ta=document.getElementById('syntax-src');
  if(ta)ta.value=s;
  recordHist(s,false);
  render(s,caret);
  scheduleAutosave();
}

funcs.setMode:
function setMode(mode){
  currentMode=mode;
  for(var i=0;i<modeBtns.length;i++)modeBtns[i].classList.toggle('active',modeBtns[i].dataset.mode===mode);
  var dp=document.getElementById('display-pane');
  var sp=document.getElementById('syntax-pane');
  var st=document.getElementById('splitter');
  buildSyntaxPane();
  if(mode==='syntax'){ dp.style.display='none'; dp.style.flex='none'; sp.style.display='flex'; sp.style.flex='1 1 auto' }
  else if(mode==='split'){ dp.style.display='flex'; dp.style.flex='1 1 50%'; sp.style.display='flex'; sp.style.flex='1 1 50%' }
  else{ dp.style.display='flex'; dp.style.flex='1 1 auto'; sp.style.display='none' }
  if(st)st.style.display=(mode==='split')?'block':'none';
  var ta=document.getElementById('syntax-src');
  if(ta)ta.value=gSrc;
  // 视图页模式按钮激活态
  ['display','syntax','split'].forEach(function(m){
    var b=document.getElementById('vb-'+m);
    if(b)b.classList.toggle('on',mode===m);
  });
  // 从语法切回显示/分屏时,按最新源码刷新显示窗格
  if(mode!=='syntax')render(gSrc);
  applyZoom(document.getElementById('sel-zoom').value);
}

funcs.fitZoom:
function fitZoom(base){
  var v=parseFloat(base)||1;
  if(currentMode==='split'){
    var w=document.getElementById('display-pane').clientWidth;
    v*=Math.min(1,(w-48)/840);
  }
  return v;
}

funcs.syncZoomSelects:
function syncZoomSelects(v){
  ['sel-zoom','sel-zoom-view'].forEach(function(id){
    var sel=document.getElementById(id);
    if(!sel)return;
    var has=[].some.call(sel.options,function(o){return o.value===v});
    if(!has){
      var o=document.createElement('option');
      o.value=v; o.textContent=Math.round(parseFloat(v)*100)+'%';
      sel.insertBefore(o,sel.querySelector('option[value="custom"]'));
    }
    sel.value=v;
  });
}

funcs.applyZoom:
function applyZoom(v){
  if(v==='custom'){
    var inp=document.getElementById('zoom-custom');
    inp.style.display='inline-block'; inp.focus();
    return;
  }
  ['zoom-custom','zoom-view-custom'].forEach(function(id){
    var inp=document.getElementById(id);
    if(inp)inp.style.display='none';
  });
  var z=fitZoom(v);
  document.getElementById('display-pane').style.zoom=z;
  document.getElementById('syntax-pane').style.zoom=z;
  syncZoomSelects(v);
}

funcs.applyZoomCustom:
function applyZoomCustom(v,which){
  var x=parseFloat(v);
  if(!(x>=30&&x<=300))return;
  var val=String(Math.round(x)/100);
  var otherInp=document.getElementById(which==='sel-zoom-view'?'zoom-view-custom':'zoom-custom');
  if(otherInp)otherInp.style.display='none';
  applyZoom(val);
}

funcs.fname:
function fname(ext){
  var e=document.getElementById('export-name');
  var d=document.getElementById('docname');
  var n=(e&&e.value.trim())?e.value.trim():(d.value||'未命名文档');
  n=n.replace(/[\\/:*?"<>|]/g,'_').replace(/\.(awen|txt|md|html?|docx?)$/i,'');
  return n+'.'+ext;
}
// 导出统一走 Bridge(桌面版原生对话框+写盘;浏览器 picker/download)
function saveWithPicker(name,content){
  Bridge.saveDialog(name,content).then(function(r){ if(r.saved)markClean() });
}
function markClean(){
  docDirty=false;
  if(activeFile>=0&&openFiles[activeFile])openFiles[activeFile].dirty=false;
  clearAutosave();          // 已落盘,草稿快照不再需要
  updateTitle();
  renderFileTabs();
}
// ═══ 自动保存/崩溃恢复(localStorage 快照)═══
var autosaveTimer=null;
function scheduleAutosave(){
  if(autosaveTimer)clearTimeout(autosaveTimer);
  autosaveTimer=setTimeout(doAutosave,2000);
}
function doAutosave(){
  try{
    localStorage.setItem('awen-autosave',JSON.stringify({
      name:document.getElementById('docname').value||'未命名文档',
      src:gSrc,time:Date.now()
    }));
  }catch(e){}
}
function loadAutosave(){
  try{ return JSON.parse(localStorage.getItem('awen-autosave')||'null') }catch(e){ return null }
}
function clearAutosave(){ try{localStorage.removeItem('awen-autosave')}catch(e){} }
function discardAutosaveDraft(){
  clearAutosave();
  document.getElementById('docname').value='未命名文档';
  setSrc('# 未命名文档\n\n');
  markClean();
}
function updateTitle(src){
  var inp=document.getElementById('docname');
  var en=document.getElementById('export-name');
  var n=inp.value||'未命名文档';
  var dm=document.getElementById('dirty-mark');
  if(dm)dm.style.display=docDirty?'inline':'none';
  if(src!=='docname'&&document.activeElement!==inp)inp.value=n;
  if(src!=='export'&&en&&document.activeElement!==en){
    en.value=n.replace(/\.[a-z0-9]+$/i,'');
  }
}
function doSave(){
  var content=buildAwenHeader()+gSrc;
  if(currentFilePath){
    Bridge.savePath(currentFilePath,content).then(function(ok){ if(ok)markClean(); else doSaveDialog(); });
  }else doSaveDialog();
}
function doSaveDialog(){
  Bridge.saveDialog(fname('awen'),buildAwenHeader()+gSrc).then(function(r){
    if(r.saved){ if(r.path)currentFilePath=r.path; markClean() }
  });
}
function doSaveAs(){ currentFilePath=null; doSaveDialog(); }
// E8:完整 .awen v0.4 manifest(nodes/next_id 与引擎 save_awen 对齐)
function buildAwenHeader(){
  var n=gNodes.length;
  return '# awen v0.4\n# nodes: '+n+'\n# next_id: '+(n+1)+'\n# res: 0\n# ---\n';
}
function newDoc(){
  if(docDirty&&!window.confirm('当前文档未保存,确定新建?'))return;
  // 多文件模型:新建=新标签;当前已是干净空白文档则复用
  var cur=openFiles[activeFile];
  if(cur&&cur.name==='未命名文档'&&!docDirty){
    document.getElementById('docname').value='未命名文档';
    setSrc('# 未命名文档\n\n');
    markClean();
    return;
  }
  if(activeFile>=0){
    applySyncNow();
    openFiles[activeFile].src=gSrc;
    openFiles[activeFile].dirty=docDirty;
  }
  document.getElementById('docname').value='未命名文档';
  setSrc('# 未命名文档\n\n');
  addFileTab('未命名文档');
  markClean();
}
// 打开文档统一入口:对话框/命令行/最近文件共用;当前是干净空白文档则复用标签
function openDocument(res){
  var name=res.name.replace(/\.(awen(\.txt)?|txt|md|markdown)$/i,'');
  var reuse=false;
  if(activeFile>=0){
    applySyncNow();
    var cur=openFiles[activeFile];
    reuse=(cur.name==='未命名文档'&&!docDirty);
    if(!reuse){ cur.src=gSrc; cur.dirty=docDirty }
  }
  document.getElementById('docname').value=name;
  setSrc(res.src);
  if(reuse){
    openFiles[activeFile]={name:name,src:gSrc,dirty:false,path:res.path||null};
    renderFileTabs();
  }else{
    addFileTab(name,res.path||null);
  }
  currentFilePath=res.path||null;
  updateTitle();
  markClean();
  pushRecentFile(name,res.path||null);
}
var currentFilePath=null;
function openFileClick(){
  Bridge.openDialog().then(function(res){ if(res)openDocument(res); });
}
function caretBlock(){
  var s=window.getSelection();
  if(!s.rangeCount)return null;
  var node=s.getRangeAt(0).startContainer;
  return node.nodeType===1?(node.closest?node.closest('[data-bid]'):null):(node.parentElement&&node.parentElement.closest('[data-bid]'));
}

