function openImagePanel(bid){
  var b=nodeByBid(bid);
  if(!b||b.kind!=='obj')return;
  var first=(b.text||'').split('\n')[0];
  var m=first.match(/^@\[(image|figure|图片)(?:\s+([^\]]*))?\]/);
  if(!m){ document.getElementById('findmsg').textContent='该对象暂不支持属性编辑'; return }
  var params=m[2]||'';
  var wm=params.match(/width:?\s*(\d+(?:\.\d+)?)\s*%/);
  var am=params.match(/align:?\s*(\w+)/);
  var old=document.getElementById('image-pop');
  if(old)old.remove();
  var pop=document.createElement('div');
  pop.id='image-pop';
  pop.style.cssText='position:fixed;z-index:210;background:#fff;border:1px solid #c9cbce;border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,.18);padding:12px;width:230px';
  var el=document.querySelector('#display-pane [data-bid="'+bid+'"]');
  var r=el?el.getBoundingClientRect():{left:100,bottom:100};
  pop.style.left=Math.min(r.left,window.innerWidth-260)+'px';
  pop.style.top=(r.bottom+8)+'px';
  pop.innerHTML='<div style="font-weight:600;font-size:12px;margin-bottom:8px">图片属性</div>'
    +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px">'
    +'<label style="font-size:12px;flex:none">宽度</label>'
    +'<input type="number" id="img-w" min="5" max="100" step="5" value="'+(wm?wm[1]:'100')+'" style="width:70px;height:24px;border:1px solid #c9cbce;border-radius:4px;font-size:12px">'
    +'<span style="font-size:12px">%</span></div>'
    +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:10px">'
    +'<label style="font-size:12px;flex:none">对齐</label>'
    +'<select id="img-a" style="height:24px;font-size:12px;border:1px solid #c9cbce;border-radius:4px">'
    +'<option value="center">居中</option><option value="left">左对齐</option><option value="right">右对齐</option>'
    +'</select></div>'
    +'<div style="display:flex;gap:8px;justify-content:flex-end">'
    +'<button class="sbtn" id="img-cancel">取消</button>'
    +'<button class="sbtn" id="img-ok" style="background:#d7e2ec;border-color:#4b6f8d">应用</button></div>';
  document.body.appendChild(pop);
  var aSel=pop.querySelector('#img-a');
  aSel.value=(am?am[1].toLowerCase():'center');
  if(['center','left','right'].indexOf(aSel.value)<0)aSel.value='center';
  btn_anchor=el||document.body;
  pop.querySelector('#img-cancel').onclick=function(){ pop.remove() };
  pop.querySelector('#img-ok').onclick=function(){
    var w=parseFloat(pop.querySelector('#img-w').value);
    if(!(w>=5&&w<=100)){ document.getElementById('findmsg').textContent='宽度需在 5-100 之间'; return }
    var al=aSel.value;
    var np=params;
    if(wm)np=np.replace(/width:?\s*\d+(?:\.\d+)?\s*%/,'width '+w+'%');
    else np=(np+' width '+w+'%').trim();
    if(am)np=np.replace(/align:?\s*\w+/,'align '+al);
    else np=(np+' align '+al).trim();
    var newLine='@['+m[1]+' '+np.trim()+']';
    var lines=gSrc.split('\n');
    for(var i=0;i<lines.length;i++){
      if(lines[i].indexOf(first)===0){ lines[i]=newLine; setSrc(lines.join('\n')); break }
    }
    pop.remove();
  };
  setTimeout(function(){
    document.addEventListener('click',function hider(ev){
      if(!pop.contains(ev.target)&&!btn_anchor.contains(ev.target)){pop.remove();document.removeEventListener('click',hider)}
    });
  },0);
}
// ═══ DOCX 导入(mammoth 本地分发,离线可用;HTML → Awen 语法转换)═══
function importDocx(){
  if(typeof mammoth==='undefined'){ alert('转换库未加载(vendor/mammoth.browser.min.js 缺失)'); return }
  var inp=document.createElement('input');
  inp.type='file'; inp.accept='.docx';
  inp.style.display='none';
  document.body.appendChild(inp);
  inp.onchange=function(){
    var f=inp.files[0];
    if(!f){ inp.remove(); return }
    var rd=new FileReader();
    rd.onload=function(){
      mammoth.convertToHtml({arrayBuffer:rd.result}).then(function(res){
        var src=htmlToAwen(res.value);
        var name=f.name.replace(/\.docx$/i,'');
        inp.remove();
        var reuse=false;
        if(activeFile>=0){
          applySyncNow();
          var cur=openFiles[activeFile];
          reuse=(cur.name==='未命名文档'&&!docDirty);
          if(!reuse){ cur.src=gSrc; cur.dirty=docDirty }
        }
        document.getElementById('docname').value=name;
        setSrc(src);
        if(reuse){ openFiles[activeFile]={name:name,src:gSrc,dirty:false,path:null}; renderFileTabs() }
        else addFileTab(name,null);
        currentFilePath=null;
        updateTitle(); markClean();
      }).catch(function(e){ inp.remove(); alert('DOCX 解析失败:'+e.message) });
    };
    rd.readAsArrayBuffer(f);
  };
  inp.click();
}
// 导出的 HTML → Awen 源码
function htmlToAwen(html){
  var doc=new DOMParser().parseFromString(html,'text/html');
  var out=[];
  function inline(node){
    var t='';
    node.childNodes.forEach(function(n){
      if(n.nodeType===3){ t+=n.textContent; return }
      if(n.nodeType!==1)return;
      if(n.tagName==='BR'){ t+=' '; return }
      var inner=inline(n);
      var tag=n.tagName;
      if(tag==='STRONG'||tag==='B')t+='**'+inner+'**';
      else if(tag==='EM'||tag==='I')t+='_'+inner+'_';
      else if(tag==='U')t+='@[u]'+inner+'@[/u]';
      else if(tag==='DEL'||tag==='S')t+='~~'+inner+'~~';
      else if(tag==='CODE')t+='`'+inner+'`';
      else if(tag==='A'){ var href=n.getAttribute('href')||''; t+='@[link '+inner+' url: '+href+']' }
      else t+=inner;
    });
    return t;
  }
  function walk(node){
    node.childNodes.forEach(function(n){
      if(n.nodeType!==1)return;
      var tag=n.tagName;
      if(/^H[1-6]$/.test(tag)){ out.push('#'.repeat(+tag.charAt(1))+' '+inline(n).trim()); out.push('') }
      else if(tag==='P'){ var t=inline(n).trim(); if(t){ out.push(t); out.push('') } }
      else if(tag==='BLOCKQUOTE'){
        var qs=n.querySelectorAll('p');
        if(qs.length)qs.forEach(function(q){ var t=inline(q).trim(); if(t)out.push('> '+t) });
        else{ var t0=inline(n).trim(); if(t0)out.push('> '+t0) }
      }
      else if(tag==='UL'||tag==='OL'){
        var idx=0;
        n.querySelectorAll(':scope > li').forEach(function(li){
          idx++;
          var t=inline(li).replace(/\s+/g,' ').trim();
          if(t)out.push((tag==='UL'?'- ':idx+'. ')+t);
        });
        out.push('');
      }
      else if(tag==='TABLE'){
        out.push('@[table imported]');
        var first=true;
        n.querySelectorAll('tr').forEach(function(tr){
          var cells=[];
          tr.querySelectorAll('th,td').forEach(function(c){ cells.push(inline(c).replace(/\|/g,'/').trim()) });
          out.push('| '+cells.join(' | ')+' |');
          if(first){ var sep='|'; for(var i=0;i<cells.length;i++)sep+=' --- |'; out.push(sep); first=false }
        });
        out.push('@[/table]');
        out.push('');
      }
      else if(tag==='IMG'){ out.push('@[image imported-image]'); out.push('') }
      else if(tag==='HR'){ out.push('---') }
      else walk(n);
    });
  }
  walk(doc.body);
  var res=[],blank=0;
  out.forEach(function(l){
    if(l===''){ blank++; if(blank<=1)res.push(l) }
    else{ blank=0; res.push(l) }
  });
  return res.join('\n');
}
// ═══ 真实图片:选本地文件,嵌入 data URI ═══
function pickImageInsert(){
  var inp=document.createElement('input');
  inp.type='file'; inp.accept='image/*';
  inp.onchange=function(){
    var f=inp.files[0];
    if(!f)return;
    if(f.size>1024*1024){alert('图片超过 1MB,原型阶段请使用小图');return}
    var rd=new FileReader();
    rd.onload=function(){
      insertRawLine('@[image '+rd.result+']');
    };
    rd.readAsDataURL(f);
  };
  inp.click();
}
function insertRawLine(line){
  var bel=inDisplayMode()?caretBlock():null;
  var lines=gSrc.split('\n');
  var at=lines.length;
  if(bel){var b=nodeByBid(bel.dataset.bid);if(b)at=b.srcEnd}
  if(at<lines.length&&lines[at].trim()!=='')line=line+'\n';
  if(at>0&&lines[at-1].trim()!=='')line='\n'+line;
  lines.splice(at,0,line);
  setSrc(lines.join('\n'));
}

