var spyTimer=null;
document.getElementById('display-pane').addEventListener('scroll',function(){
  document.getElementById('minibar').style.display='none';
  if(spyTimer)clearTimeout(spyTimer);
  spyTimer=setTimeout(spyOutline,160);
