funcs.importDocx:
function importDocx(){
  if(typeof mammoth==='undefined'){ alert('转换库未加载(vendor/mammoth.browser.min.js 缺失)'); return }
  var inp=document.createElement('input');
  inp.type='file'; inp.accept='.docx';
