    el.innerHTML='<span style="color:#9aa0a6;font-size:12px">暂无</span>';
    return;
  }
  list.forEach(function(f){
    var d=document.createElement('div');
    d.className='recent-item';
    d.textContent=f.name;
    d.title=(f.path||f.name)+(f.path?'':'（浏览器版仅记录名称,点击重新选择文件）');
    if(!f.path){
      d.style.color='#9aa0a6';
      d.style.fontStyle='italic';
    }
    d.onclick=function(){
      if(f.path&&Bridge.native) Bridge.openPath(f.path).then(function(res){ if(res)openDocument(res) });
      else openFileClick();
    };
    el.appendChild(d);
  });
}

funcs.renderFileTabs:
function renderFileTabs(){
  var bar=document.getElementById('filetabs');
  bar.innerHTML='';
  openFiles.forEach(function(f,i){
    var t=document.createElement('div');
    t.className='ftab'+(i===activeFile?' active':'')+(f.dirty?' dirty':'');
    t.title=f.name+'（中键或 ✕ 关闭）';
    t.innerHTML='<span class="fdirty"></span><span>'+f.name.replace(/</g,'&lt;')+'</span><span class="fclose" data-i="'+i+'">✕</span>';
    t.onclick=function(ev){
      if(ev.target.classList.contains('fclose')){closeFile(i);return}
      switchFile(i);
    };
    t.onauxclick=function(ev){ if(ev.button===1)closeFile(i) };   // 中键关闭
    bar.appendChild(t);
  });
}

funcs.switchFile:
function switchFile(i){
  if(i===activeFile)return;
  applySyncNow();
  if(activeFile>=0){
    openFiles[activeFile].src=gSrc;
    openFiles[activeFile].dirty=docDirty;
  }
  activeFile=i;
  var f=openFiles[i];
  currentFilePath=f.path||null;
  document.getElementById('docname').value=f.name;
  setSrc(f.src);
  docDirty=f.dirty;
  // 撤销栈按文件隔离:切换后从当前内容重开历史,避免跨文件串档
  hist=[f.src]; histIdx=0; histTime=0;
  updateUndoButtons();
  updateTitle();
  renderFileTabs();
}

funcs.closeFile:
function closeFile(i){
  if(openFiles[i].dirty&&!window.confirm('「'+openFiles[i].name+'」未保存,确定关闭?'))return;
  openFiles.splice(i,1);
  if(activeFile>=i)activeFile--;
  if(activeFile<0)activeFile=0;
  if(activeFile>=openFiles.length)activeFile=openFiles.length-1;
  if(!openFiles.length){ newDoc(); return }
  var f=openFiles[activeFile];
  currentFilePath=f.path||null;
  document.getElementById('docname').value=f.name;
  setSrc(f.src);
  docDirty=f.dirty;
  updateTitle();
  renderFileTabs();
}

funcs.showWordCount:
function showWordCount(){
  var chars=0, charsSp=0, paras=0, words=0;
  var paper=document.querySelector('#display-pane .paper');
  if(paper){
    var txt=paper.textContent;
    charsSp=txt.replace(/\s{2,}/g,' ').trim().length;
    chars=txt.replace(/\s/g,'').length;
    paras=gNodes.filter(function(n){return n.kind==='para'||n.kind==='heading'}).length;
  }
  var pop=document.getElementById('diagpop');
  pop.innerHTML='<div style="font-weight:600;margin-bottom:6px">字数统计</div>'
    +'<div>字数(不计空格): <b>'+chars+'</b></div>'
    +'<div>字符数(计空格): <b>'+charsSp+'</b></div>'
    +'<div>段落数: <b>'+paras+'</b></div>'
    +'<div>页数: <b>'+gPages.length+'</b></div>';
  pop.style.display='block';
  setTimeout(function(){pop.style.display='none'},4000);
}

funcs.toggleMarks:
