funcs.zoomEntry:
function zoomEntry(v,which){
  if(v==='custom'){
    var inp=document.getElementById(which==='sel-zoom-view'?'zoom-view-custom':'zoom-custom');
    inp.style.display='inline-block'; inp.focus();
    return;
  }
  applyZoom(v);
}

funcs.stepSize:
function stepSize(d){
  var sel=document.getElementById('sel-size');
  var cur=parseFloat(sel.value)||10.5;
  var v;
  if(d>0){
    v=SIZE_LADDER.find(function(x){return x>cur+0.01});
    if(v===undefined)v=SIZE_LADDER[SIZE_LADDER.length-1];
  }else{
    v=null;
    for(var i=SIZE_LADDER.length-1;i>=0;i--){ if(SIZE_LADDER[i]<cur-0.01){v=SIZE_LADDER[i];break} }
    if(v===null)v=SIZE_LADDER[0];
  }
  var has=[].some.call(sel.options,function(o){return parseFloat(o.value)===v});
  if(!has){
    var o=document.createElement('option');
    o.value=String(v); o.textContent=(v===Math.round(v)?v:v.toFixed(1))+' 号';
    sel.appendChild(o);
  }
  sel.value=String(v);
  applySize(String(v));
}

funcs.spyOutline:
function spyOutline(){
  var heads=document.querySelectorAll('#display-pane [data-kind="heading"]');
  var pane=document.getElementById('display-pane');
  var top=pane.getBoundingClientRect().top;
  var threshold=pane.clientHeight*0.3;
  var cur=null;
  heads.forEach(function(h){
    var r=h.getBoundingClientRect();
    if(r.top-top<=threshold)cur=h;
  });
  document.querySelectorAll('.outline-item').forEach(function(o){o.classList.remove('active')});
  if(cur){
    var bid=cur.dataset.bid;
    document.querySelectorAll('.outline-item').forEach(function(o){
      if(o.dataset.bid==bid)o.classList.add('active');
    });
  }
}
